CREATE OR REPLACE TABLE "Gross Margin" ENGINE = Memory AS
SELECT u."Customer" AS "Customer", u."SKU" AS "SKU", u."Versions" AS "Versions", u."Years" AS "Years", u."Months" AS "Months", sum(u.v) AS v
